func validate(c constraint) error {
	if c.Property == "" {
		return errors.New("empty property")
	}
	if c.Operator == "" {
		return errors.New("empty operator")
	}
	op := strings.ToLower(c.Operator)
	if _, ok := validOperators[op]; !ok {
		return fmt.Errorf("unsupported operator: %q", op)
	}
	var allowed map[string]struct{}
	switch c.Type {
	case flipt.ComparisonType_STRING_COMPARISON_TYPE:
		allowed = stringOperators
	case flipt.ComparisonType_NUMBER_COMPARISON_TYPE:
		allowed = numberOperators
	case flipt.ComparisonType_BOOLEAN_COMPARISON_TYPE:
		allowed = booleanOperators
	default:
		return ErrInvalid("unknown constraint type")
	}
	if _, ok := allowed[op]; !ok {
		return ErrInvalidf("operator %q is not valid for constraint type %s", op, c.Type.String())
	}

	return nil
}

func matchesString(c constraint, v string) bool {
	value := strings.TrimSpace(c.Value)
	v = strings.TrimSpace(v)
	switch strings.ToLower(c.Operator) {
	case opEQ:
		return value == v
	case opNEQ:
		return value != v
	case opEmpty:
		return len(strings.TrimSpace(v)) == 0
	case opNotEmpty:
		return len(v) != 0
	case opPresent:
		return len(v) != 0
	case opNotPresent:
		return len(v) == 0
	case opPrefix:
		return strings.HasPrefix(strings.TrimSpace(v), value)
	case opSuffix:
		return strings.HasSuffix(strings.TrimSpace(v), value)
	}
	return false
}

func matchesNumber(c constraint, v string) (bool, error) {
	op := strings.ToLower(c.Operator)
	v = strings.TrimSpace(v)
	switch op {
	case opNotPresent:
		return len(strings.TrimSpace(v)) == 0, nil
	case opPresent:
		return len(strings.TrimSpace(v)) != 0, nil
	}

	// can't parse an empty string
	if v == "" {
		return false, nil
	}

	n, err := strconv.ParseFloat(v, 64)
	if err != nil {
		return false, fmt.Errorf("parsing number from %q", v)
	}
	if math.IsNaN(n) || math.IsInf(n, 0) {
		return false, fmt.Errorf("parsing number from %q", v)
	}

	value, err := strconv.ParseFloat(strings.TrimSpace(c.Value), 64)
	if err != nil {
		return false, fmt.Errorf("parsing number from %q", c.Value)
	}
	if math.IsNaN(value) || math.IsInf(value, 0) {
		return false, fmt.Errorf("parsing number from %q", c.Value)
	}

	switch op {
	case opEQ:
		return value == n, nil
	case opNEQ:
		return value != n, nil
	case opLT:
		return n < value, nil
	case opLTE:
		return n <= value, nil
	case opGT:
		return n > value, nil
	case opGTE:
		return n >= value, nil
	}

	return false, nil
}
